import Foundation

/// Namespace for set 2's frames.json text (Originals*.swift, generated by tools/originals-set2).
public enum OriginalArt {}

/// One built-in original character (set 2): its names and frames.json art. The Mac draws it as OriginalCharacterSet2.
public struct OriginalInfo {
    public let id: String
    public let displayName: String
    /// The signature move shown by `.special`, for the picker preview.
    public let specialName: String
    /// One line for the preview page.
    public let blurb: String
    public let json: String

    public static let all: [OriginalInfo] = [
        OriginalInfo(id: "original-tan-cat", displayName: L("태닝 고양이"), specialName: L("킥플립"),
                     blurb: L("햇볕에 그을린 스케이터 고양이. 킥플립 한 방에 윙크까지 해요."), json: OriginalArt.tanCat),
    ]
}

/// frames.json art with "extras" (hungry, eat, special), parsed: RGBA frames on the shared 34x20 canvas, facing right.
public struct OriginalFrames {
    /// RGBA frames in DogPose order, 34x20.
    public let poseRGBA: [[[UInt8]]]
    public let extraRGBA: [ExtraMotion: [[UInt8]]]
    public let outline: PixelColor
    public let palette: [String: String]

    /// `palette`: 꾸미기 colours in place of the drawn ones.
    public init(json: String, palette: [String: String]? = nil) {
        // Bundled art, checked by OriginalSet2Tests, so a parse failure is a build mistake.
        let data = Data(json.utf8)
        var art = try! FrameArt.parse(data)
        if let palette { art.palette = palette }
        self.palette = art.palette
        var colors: [Character: PixelColor] = [:]
        for (key, hex) in art.palette { if let c = key.first { colors[c] = PixelColor(hex: hex) } }
        let extras = ((try? JSONSerialization.jsonObject(with: data)) as? [String: Any])?["extras"] as? [String: [[String]]] ?? [:]
        var extraRGBA: [ExtraMotion: [[UInt8]]] = [:]
        for motion in ExtraMotion.allCases {
            extraRGBA[motion] = extras[motion.rawValue]?.map { AsciiArt.rgba($0.joined(separator: "\n"), colors) }
        }
        poseRGBA = art.nativeFrames()
        self.extraRGBA = extraRGBA
        outline = BarArt.outlineColor(poseRGBA[DogPose.walk.rawValue][0])
    }
}
